 function playerStats(p:Player):Record<StatKey,number>{const defaults:Record<StatKey,number>={accuracy:30,finishing:30,passing:30,heading:30,dribbling:30,control:30,tackling:30,defense:30,strength:30,jump:30,stamina:30,speed:30,reading:30,vision:30};return{...defaults,...p.stats}}
